let state = loadState();
window.ShineProState = state;

function loadState() {
  try { const saved = localStorage.getItem(STORAGE_KEY); return saved ? { ...seedState, ...JSON.parse(saved) } : structuredClone(seedState); }
  catch { return structuredClone(seedState); }
}
function persist() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); window.ShineProState = state; }
function money(value, compact = false) { const n = Math.round(Number(value || 0)); if (compact && Math.abs(n) >= 1000000) return `${(n / 1000000).toFixed(n % 1000000 ? 1 : 0)}M`; if (compact && Math.abs(n) >= 1000) return `${Math.round(n / 1000)}k`; return n.toLocaleString('en-US'); }
function toman(value, compact = false) { return `${money(value, compact)} <small>toman</small>`; }
function getWorker(id) { return state.workers.find(w => w.id === id) || { name: 'Unassigned', initials: '—', role: 'Worker', color: 'slate' }; }
function getJob(id = state.selectedJobId) { return state.jobs.find(j => j.id === id); }
function commission(job) { const base = Math.max(0, Number(job.finalPrice || 0)); return (job.assignments || []).map(a => ({ ...a, final: a.commissionType === 'Fixed' ? Number(a.fixedAmount || 0) : Math.round(base * Number(a.percentage || 0) / 100), worker: getWorker(a.workerId) })); }
function totalCommission(job) { return commission(job).reduce((sum, a) => sum + a.final, 0); }
function statusMeta(status) { return { Waiting: ['waiting', 'Waiting'], Assigned: ['waiting', 'Assigned'], 'In Progress': ['progress', 'In progress'], 'Ready for Quality Check': ['quality', 'Quality check'], 'Rework Required': ['quality', 'Rework required'], 'Ready for Payment': ['payment', 'Ready for payment'], Completed: ['payment', 'Completed'], Cancelled: ['quality', 'Cancelled'], Refunded: ['quality', 'Refunded'] }[status] || ['waiting', status]; }
function statusPill(status) { const [kind, label] = statusMeta(status); return `<span class="status-pill ${kind === 'progress' ? '' : kind === 'payment' ? 'green' : kind === 'quality' ? 'red' : 'amber'}">${label}</span>`; }
function filterMatches(job, filter) { if (filter === 'all') return true; if (filter === 'waiting') return ['Waiting', 'Assigned'].includes(job.status); if (filter === 'progress') return ['In Progress', 'Rework Required'].includes(job.status); if (filter === 'quality') return job.status === 'Ready for Quality Check'; if (filter === 'payment') return job.status === 'Ready for Payment'; return true; }
function roleLabel() { return state.role === 'Owner' ? 'Owner view' : `${state.role} view`; }
function can(action) { const role = state.role; const matrix = { quality: ['Owner', 'Company Administrator', 'Branch Manager', 'Quality Controller'], discount: ['Owner', 'Company Administrator', 'Branch Manager'], payment: ['Owner', 'Branch Manager', 'Cashier', 'Accountant'], expense: ['Owner', 'Company Administrator', 'Branch Manager', 'Cashier', 'Accountant'], payroll: ['Owner', 'Accountant'], inventory: ['Owner', 'Company Administrator', 'Inventory Manager', 'Branch Manager'], settings: ['Owner', 'Platform Super Admin', 'Company Administrator'], customer: ['Owner', 'Company Administrator', 'Branch Manager', 'Cashier', 'Customer'], correction: ['Owner', 'Accountant'] }; return !matrix[action] || matrix[action].includes(role); }

function render() {
  document.querySelectorAll('.nav-item[data-view]').forEach(btn => btn.classList.toggle('active', btn.dataset.view === currentView));
  document.querySelectorAll('.view').forEach(view => view.classList.toggle('active-view', view.id === `view-${currentView}`));
  document.getElementById('role-select').value = roleLabel();
  const greeting = state.role === 'Worker' ? 'Your shift at a glance' : state.role === 'Cashier' ? 'Ready for the next vehicle' : `Good afternoon, Morteza <span class="wave">✦</span>`;
  document.getElementById('page-title').innerHTML = greeting;
  renderMetrics(); renderQueue(); renderOperations(); renderDetail(); decorateDetailActions(); renderEarnings(); renderCash(); renderReports(); renderTeam(); renderCustomers(); renderInventory(); renderInbox(); renderSettings(); ensureLanguageButton();
}

let currentView = 'overview';
function renderMetrics() {
  const completed = state.jobs.filter(j => j.status === 'Completed').length + 17;
  const revenue = state.jobs.filter(j => j.paymentStatus === 'Paid').reduce((s, j) => s + j.finalPrice, 0) + 12500000;
  const tips = 460000;
  const metrics = state.role === 'Worker' ? [
    ['Assigned today', state.jobs.filter(j => j.assignments.some(a => a.workerId === 'w4')).length, '', '3 active tasks', 'green'],
    ['Earnings today', 1850000, 'toman', '↗ 14% vs yesterday', 'green'],
    ['Tips this week', tips, 'toman', 'Shared fairly across jobs', 'green'],
    ['Quality score', '97', '%', 'Above 95% bonus threshold', 'green']
  ] : [
    ['Revenue today', revenue, 'toman', '↗ 18.4% vs last Tuesday', 'green'],
    ['Cars completed', completed, '', '↗ 6 more than yesterday', 'green'],
    ['Worker commissions', 3400000, 'toman', '27 active assignments', 'green'],
    ['Contribution margin', 7800000, 'toman', '61% after direct costs', 'green']
  ];
  const target = currentView === 'earnings' ? document.getElementById('earning-metrics') : document.getElementById('metric-grid');
  if (currentView === 'earnings') { document.getElementById('earning-metrics').innerHTML = metrics.map(m => metricTemplate(...m)).join(''); }
  else document.getElementById('metric-grid').innerHTML = metrics.map(m => metricTemplate(...m)).join('');
}
function metricTemplate(label, value, suffix, foot, color) { return `<div class="metric-card"><span class="metric-label">${label}</span><span class="metric-icon">${label.includes('Cash') ? '₮' : label.includes('Quality') ? '◇' : label.includes('Cars') ? '◇' : '◒'}</span><strong class="metric-value">${typeof value === 'number' ? money(value, true) : value}<small>${suffix}</small></strong><span class="metric-foot ${color === 'warn' ? 'warn' : ''}">${foot}</span></div>`; }

function renderQueue() {
  const list = document.getElementById('queue-list'); if (!list) return;
  let jobs = state.jobs.filter(j => filterMatches(j, state.jobFilter));
  if (state.role === 'Worker') jobs = jobs.filter(j => j.assignments.some(a => a.workerId === 'w4'));
  list.innerHTML = jobs.map(job => {
    const [kind] = statusMeta(job.status); const people = [...new Set(job.assignments.map(a => getWorker(a.workerId).initials))];
    return `<div class="queue-row ${job.id === state.selectedJobId ? 'selected' : ''}" data-job-id="${job.id}"><span class="status-dot ${kind}"></span><div class="queue-main"><b>${job.code.replace('CW-2026-', '#')}</b><small>${job.plate} · ${job.vehicleType}</small></div><div class="queue-service"><b>${job.service}</b><small>${job.bay}</small></div><div class="queue-workers"><div class="workers-avatars">${people.slice(0, 3).map(i => `<span class="mini-avatar">${i}</span>`).join('')}${people.length > 3 ? '<span class="mini-avatar more-avatar">+' + (people.length - 3) + '</span>' : ''}</div></div><div class="queue-price">${money(job.finalPrice, true)}</div><div class="queue-time">${job.status === 'Completed' ? 'Done' : `${waitingMinutes(job.arrival)}m`}</div></div>`;
  }).join('') || '<div class="empty-state"><b>No jobs in this view</b>Try a different filter.</div>';
  const chart = document.getElementById('bar-chart'); if (chart) chart.innerHTML = [52, 67, 47, 76, 40, 0, 0].map((h, i) => `<span class="bar ${i === 3 ? 'highlight' : ''}" style="height:${h}%"></span>`).join('');
  const pulse = document.getElementById('team-pulse'); if (pulse) pulse.innerHTML = state.workers.filter(w => w.present).slice(0, 4).map(w => `<div class="team-person"><div class="avatar avatar-${w.color}">${w.initials}</div><div><b>${w.name.split(' ')[0]}</b><small>${w.role === 'Car-wash worker' ? 'On bay' : w.title}</small></div></div>`).join('');
}
function waitingMinutes(arrival) { const [h, m] = arrival.split(':').map(Number); return Math.max(0, 13 * 60 + 42 - (h * 60 + m)); }

function renderOperations() {
  const list = document.getElementById('operations-list'); if (!list) return;
  const search = (document.getElementById('job-search')?.value || '').toLowerCase();
  let jobs = state.jobs.filter(j => filterMatches(j, state.jobFilter) && [j.code, j.plate, j.customer, j.service].join(' ').toLowerCase().includes(search));
  if (state.role === 'Worker') jobs = jobs.filter(j => j.assignments.some(a => a.workerId === 'w4'));
  list.innerHTML = `<div class="operation-row operation-heading"><div><span class="section-kicker">JOB</span></div><div><span class="section-kicker">SERVICE</span></div><div><span class="section-kicker">STATUS</span></div><div><span class="section-kicker">WORKERS</span></div><div><span class="section-kicker">TOTAL</span></div></div>` + (jobs.map(j => `<div class="operation-row ${j.id === state.selectedJobId ? 'selected' : ''}" data-job-id="${j.id}"><div><b>${j.code.replace('CW-2026-', '#')}</b><small>${j.plate}</small></div><div><b>${j.service}</b><small>${j.vehicleType} · ${j.arrival}</small></div><div>${statusPill(j.status)}</div><div><small>${j.assignments.length ? j.assignments.map(a => getWorker(a.workerId).name.split(' ')[0]).join(', ') : 'Unassigned'}</small></div><div class="row-price">${money(j.finalPrice, true)}</div></div>`).join('') || '<div class="empty-state"><b>No matching jobs</b>Nothing matches your current search.</div>');
}

function renderDetail() {
  const detail = document.getElementById('job-detail'); if (!detail) return; const job = getJob();
  if (!job) { detail.innerHTML = '<div class="detail-empty"><div><span>◈</span>Select a job to inspect its details.</div></div>'; return; }
  const rows = commission(job); const canQuality = can('quality'); const canPayment = can('payment');
  const action = job.status === 'Waiting' ? `<button class="primary-button" data-action="assign">Assign workers</button>` : job.status === 'Assigned' ? `<button class="primary-button" data-action="start">Start work</button>` : job.status === 'In Progress' ? `<button class="primary-button" data-action="complete-task">Mark tasks complete</button>` : job.status === 'Ready for Quality Check' ? `${canQuality ? '<button class="primary-button" data-action="approve-quality">Approve quality</button><button class="ghost-button" data-action="rework">Request rework</button>' : '<button class="ghost-button" data-action="quality-locked">Quality approval required</button>'}` : job.status === 'Ready for Payment' ? `${canPayment ? '<button class="primary-button" data-action="payment">Collect payment</button>' : '<button class="ghost-button" data-action="payment-locked">Payment restricted</button>'}` : '<button class="ghost-button" data-action="history">View immutable history</button>';
  detail.innerHTML = `<div class="detail-top"><div class="detail-code"><div><h3>${job.code}</h3><small>${job.arrival} arrival · ${job.bay}</small></div><button class="icon-button detail-close">×</button></div><div class="detail-meta">${statusPill(job.status)}<span class="status-pill ${job.paymentStatus === 'Paid' ? 'green' : 'amber'}">${job.paymentStatus}</span>${job.discount ? '<span class="status-pill amber">Discounted</span>' : ''}</div></div><div class="detail-section"><h4>Vehicle & customer</h4><div class="vehicle-info"><div class="vehicle-icon">▱</div><div><b>${job.brand} ${job.model} · ${job.vehicleType}</b><small>${job.plate} · ${job.color}</small></div></div><div class="detail-line"><span>Customer</span><b>${job.customer}</b></div><div class="detail-line"><span>Phone</span><b>${job.phone || 'Walk-in customer'}</b></div></div><div class="detail-section"><h4>Service snapshot</h4><div class="detail-line"><span>${job.service} · ${job.vehicleType}</span><b>${money(job.originalPrice)} toman</b></div>${job.discount ? `<div class="detail-line"><span>Discount · ${job.discountReason || 'Approved discount'}</span><b class="amount" style="color:var(--coral)">−${money(job.discount)} toman</b></div>` : ''}<div class="detail-line"><span>Final customer price</span><b>${money(job.finalPrice)} toman</b></div><div class="payment-box"><div class="detail-line"><span>Commission base</span><b>${money(job.finalPrice)} toman</b></div><div class="detail-line"><span>Worker commission pool</span><b>${money(totalCommission(job))} toman</b></div></div></div><div class="detail-section"><h4>Worker assignments <span style="float:right;color:#8d9d96;font-weight:400">${rows.length} assigned</span></h4>${rows.length ? rows.map(a => `<div class="assign-row"><div class="avatar avatar-${a.worker.color}">${a.worker.initials}</div><div><b>${a.worker.name}</b><small>${a.role} · ${a.status}</small></div><span class="commission-amt">${money(a.final)} <small>(${a.percentage}%)</small></span></div>`).join('') : '<div class="empty-state">No workers assigned yet.</div>'}</div>${job.notes || job.existingDamage ? `<div class="detail-section"><h4>Notes</h4>${job.notes ? `<div class="detail-line"><span>Job note</span><b>${job.notes}</b></div>` : ''}${job.existingDamage ? `<div class="detail-line"><span>Existing damage</span><b>${job.existingDamage}</b></div>` : ''}</div>` : ''}${job.paymentStatus === 'Paid' ? `<div class="detail-section"><h4>Payment recorded</h4>${job.payments.map(p => `<div class="detail-line"><span>${p.method}</span><b>${money(p.amount)} toman</b></div>`).join('')}</div>` : ''}<div class="detail-actions">${action}</div>`;
}

function renderEarnings() {
  const table = document.getElementById('earnings-table'); if (!table) return;
  const workers = state.role === 'Worker' ? state.workers.filter(w => w.id === 'w4') : state.workers.filter(w => ['Car-wash worker', 'Team Leader'].includes(w.role));
  table.innerHTML = workers.map(w => { const assigned = state.jobs.flatMap(j => commission(j).filter(a => a.workerId === w.id)); const comm = assigned.reduce((s, a) => s + a.final, 0); const tips = w.id === 'w4' ? 180000 : w.id === 'w5' ? 140000 : 90000; const payable = comm + tips; w.payable = payable; return `<tr><td><div class="worker-cell"><div class="avatar avatar-${w.color}">${w.initials}</div><div><b>${w.name}</b><small>${w.title}</small></div></div></td><td>${w.completed}</td><td class="amount">${money(comm)} toman</td><td class="amount">${money(tips)} toman</td><td class="amount">—</td><td class="amount"><b>${money(payable)} toman</b></td><td>${w.id === 'w4' ? '<span class="status-pill amber">Needs review</span>' : '<span class="status-pill green">Estimated</span>'}</td></tr>`; }).join('');
  const job = getJob(); const breakdown = document.getElementById('commission-breakdown'); if (!breakdown || !job) return;
  breakdown.innerHTML = `<div class="breakdown-wrap"><div class="breakdown-note">Final discounted price <b>${money(job.finalPrice)} toman</b> × role rate. Commission remains <b>${job.status === 'Completed' ? 'Earned' : 'Pending quality approval'}</b> until every gate is passed.</div>${commission(job).map(a => `<div class="breakdown-row"><div class="avatar avatar-${a.worker.color}">${a.worker.initials}</div><div><b>${a.worker.name}</b><small>${a.role} · ${a.percentage}% of net service revenue · ${a.status}</small></div><span class="amount">${money(a.final)} toman</span></div>`).join('')}<div class="detail-line" style="padding-top:12px"><span>Total worker commission</span><b>${money(totalCommission(job))} toman</b></div></div>`;
}

function renderCash() {
  const c = state.cash; const expected = c.opening + c.payments + c.added - c.refunds - c.expenses - c.removed; const expectedEl = document.getElementById('expected-cash'); if (expectedEl) expectedEl.innerHTML = `${money(expected, true)}<small> toman</small>`;
  const breakdown = document.getElementById('cash-breakdown'); if (breakdown) breakdown.innerHTML = [['Opening cash', c.opening, ''], ['Cash payments', c.payments, 'positive'], ['Cash added', c.added, 'positive'], ['Cash refunds', -c.refunds, 'negative'], ['Cash expenses', -c.expenses, 'negative'], ['Cash removed', -c.removed, 'negative']].map(([label, amount, kind]) => `<div class="cash-entry ${kind}"><span>${label}</span><b>${amount < 0 ? '−' : ''}${money(Math.abs(amount), true)}</b></div>`).join('');
}
function renderReports() { const list = document.getElementById('audit-list'); if (list) list.innerHTML = state.audit.map(a => `<div class="audit-row"><span class="audit-dot"></span><div><b>${a.text}</b><small>${a.detail}</small></div><span class="audit-time">${a.time}</span></div>`).join(''); }
function renderTeam() { const grid = document.getElementById('team-grid'); if (!grid) return; grid.innerHTML = state.workers.map(w => `<article class="team-card"><div class="team-card-top"><div class="avatar avatar-${w.color}">${w.initials}</div><span class="status-pill ${w.present ? 'green' : ''}">${w.present ? 'On shift' : 'Off shift'}</span></div><h3>${w.name}</h3><p>${w.title} · ${w.role}</p><div class="team-card-stats"><div><span>Quality score</span><b>${w.quality}%</b></div><div><span>Jobs this week</span><b>${w.completed}</b></div><div><span>Shift</span><b>${w.present ? 'AM' : '—'}</b></div></div></article>`).join(''); }

function openModal(title, subtitle, body, footer = '') { document.getElementById('modal').innerHTML = `<div class="modal-header"><div><h3>${title}</h3><p>${subtitle}</p></div><button class="modal-close" data-close-modal>×</button></div><div class="modal-body">${body}</div>${footer ? `<div class="modal-footer">${footer}</div>` : ''}`; document.getElementById('modal-backdrop').classList.add('open'); }
function closeModal() { document.getElementById('modal-backdrop').classList.remove('open'); }
function toast(message, warning = false) { const wrap = document.getElementById('toast-container'); const node = document.createElement('div'); node.className = `toast ${warning ? 'warning' : ''}`; node.innerHTML = message; wrap.appendChild(node); setTimeout(() => node.remove(), 3700); }
function addAudit(text, detail) { state.audit.unshift({ text, detail, time: 'Just now' }); state.audit = state.audit.slice(0, 8); }

function newJobModal() {
  const serviceOptions = Object.keys(serviceCatalog).map(s => `<option>${s}</option>`).join('');
  const workers = state.workers.filter(w => w.role === 'Car-wash worker' || w.role === 'Team Leader').map(w => `<label class="check-option"><input type="checkbox" name="workers" value="${w.id}">${w.name}</label>`).join('');
  openModal('Register a new vehicle', 'Create a historical service and pricing snapshot at arrival.', `<form id="new-job-form"><div class="form-grid"><div class="form-field"><label>Registration plate *</label><input name="plate" required placeholder="21 ب 482 ایران 11" /></div><div class="form-field"><label>Vehicle type *</label><select name="vehicleType"><option>Small</option><option selected>Sedan</option><option>SUV</option><option>Van</option></select></div><div class="form-field"><label>Brand</label><input name="brand" placeholder="Kia" /></div><div class="form-field"><label>Model</label><input name="model" placeholder="Cerato" /></div><div class="form-field"><label>Customer name</label><input name="customer" placeholder="Optional walk-in customer" /></div><div class="form-field"><label>Customer phone</label><input name="phone" placeholder="0912 ..." /></div><div class="form-field full"><label>Service *</label><select name="service" id="new-service">${serviceOptions}</select></div><div class="form-field"><label>Approved discount (toman)</label><input name="discount" type="number" min="0" value="0" /></div><div class="form-field"><label>Assigned bay</label><select name="bay"><option>Unassigned</option><option>Bay 01</option><option>Bay 02</option><option>Bay 03</option><option>Bay 04</option><option>Bay 05</option></select></div><div class="form-field full"><label>Assign workers (optional)</label><div class="checkbox-list">${workers}</div></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="new-job-form">Create job</button>');
  const updatePrice = () => { const form = document.getElementById('new-job-form'); const service = serviceCatalog[form.service.value]; form.discount.max = service.prices[form.vehicleType.value]; };
  document.getElementById('new-service').addEventListener('change', updatePrice); updatePrice();
}
function paymentModal(job) { openModal('Collect customer payment', `${job.code} · ${job.service} · ${job.customer}`, `<form id="payment-form"><div class="payment-box" style="margin:0 0 16px"><div class="detail-line"><span>Amount due</span><b>${money(job.finalPrice)} toman</b></div><div class="detail-line"><span>Commission base</span><b>${money(job.finalPrice)} toman</b></div></div><div class="form-grid"><div class="form-field"><label>Payment method *</label><select name="method"><option>Cash</option><option>Card</option><option>Bank transfer</option><option>Customer credit</option></select></div><div class="form-field"><label>Amount received *</label><input name="amount" type="number" value="${job.finalPrice}" min="0" required /></div><div class="form-field full"><label>Tip (tracked separately)</label><input name="tip" type="number" value="0" min="0" /></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="payment-form">Record payment</button>'); }
function expenseModal() { openModal('Add branch expense', 'Every expense creates an auditable ledger record.', `<form id="expense-form"><div class="form-grid"><div class="form-field full"><label>Description *</label><input name="name" required placeholder="e.g. Cleaning supplies" /></div><div class="form-field"><label>Category *</label><select name="category"><option>Direct job expense</option><option>Daily branch expense</option><option>Monthly operating expense</option><option>Inventory purchase</option><option>Maintenance</option><option>Other</option></select></div><div class="form-field"><label>Amount (toman) *</label><input name="amount" type="number" min="0" required placeholder="0" /></div><div class="form-field"><label>Payment source</label><select name="source"><option>Cash</option><option>Card</option><option>Bank transfer</option></select></div><div class="form-field"><label>Status</label><select name="status"><option>Submitted</option><option>Draft</option><option>Approved</option></select></div><div class="form-field full"><label>Supporting note</label><textarea name="note" placeholder="Why was this expense necessary?"></textarea></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="expense-form">Save expense</button>'); }
function shiftModal() { const c = state.cash; const expected = c.opening + c.payments + c.added - c.refunds - c.expenses - c.removed; openModal('Morning shift summary', 'Live control check · Tuesday 28 July 2026', `<div class="metric-grid" style="margin:0 0 12px;grid-template-columns:1fr 1fr"><div class="metric-card"><span class="metric-label">Completed</span><strong class="metric-value">${state.jobs.filter(j => j.status === 'Completed').length + 17}</strong><span class="metric-foot">vehicles today</span></div><div class="metric-card"><span class="metric-label">Expected cash</span><strong class="metric-value">${money(expected, true)}<small>toman</small></strong><span class="metric-foot ${c.actual !== expected ? 'warn' : ''}">${c.actual !== expected ? `Difference ${money(c.actual - expected)} toman` : 'Balanced'}</span></div></div><div class="detail-line"><span>Open jobs</span><b>${state.jobs.filter(j => j.status !== 'Completed').length}</b></div><div class="detail-line"><span>Workers present</span><b>${state.workers.filter(w => w.present).length} / ${state.workers.length}</b></div><div class="detail-line"><span>Discounts today</span><b>3 · ${money(135000)} toman</b></div><div class="detail-line"><span>Unpaid worker earnings</span><b>${money(3400000)} toman</b></div>`, '<button class="primary-button" data-close-modal>Done</button>'); }
function rolesModal() { openModal('Permission matrix', 'Role-based controls are enforced at the action layer in this prototype.', `<table class="permission-table"><thead><tr><th>Capability</th><th>Owner</th><th>Manager</th><th>Cashier</th><th>Worker</th></tr></thead><tbody>${[['Approve quality','Yes','Yes','No','No'],['Discount ≤ 10%','Yes','Yes','Request','No'],['Record payment','Yes','Yes','Yes','No'],['Approve payroll','Yes','No','No','No'],['View own earnings','Yes','Yes','Yes','Yes'],['View another worker pay','Yes','Yes','No','No']].map(r => `<tr><td><b>${r[0]}</b></td>${r.slice(1).map(v => `<td><span class="role-badge">${v}</span></td>`).join('')}</tr>`).join('')}</tbody></table>`, '<button class="primary-button" data-close-modal>Close</button>'); }
function notificationModal() { openModal('Review queue', 'Three operational items need attention.', `<div class="notification-list"><div class="notification"><span class="review-icon amber">%</span><div><b>2 discounts waiting for approval</b><small>Large discount authority is recorded separately from the price snapshot.</small></div></div><div class="notification"><span class="review-icon red">◷</span><div><b>CW-2026-000124 needs quality approval</b><small>Commissions remain pending until approval.</small></div></div><div class="notification"><span class="review-icon blue">₮</span><div><b>Yesterday’s cash difference is −600,000 toman</b><small>Owner review required above the 500,000 toman threshold.</small></div></div></div>`, '<button class="primary-button" data-close-modal>Close</button>'); }

function handleAction(action) {
  const job = getJob(); if (!job) return;
  if (action === 'quality-locked' || action === 'payment-locked') return toast('<strong>Permission required.</strong> Switch to an authorized role to complete this action.', true);
  if (action === 'assign') { job.assignments = [assignment('w4', serviceCatalog[job.service].rules[0][0], serviceCatalog[job.service].rules[0][1], 'Assigned'), assignment('w6', serviceCatalog[job.service].rules[1]?.[0] || 'Assistant', serviceCatalog[job.service].rules[1]?.[1] || 5, 'Assigned')]; job.status = 'Assigned'; addAudit(`Assigned workers to ${job.code}`, 'Assignment snapshot created'); toast(`<strong>${job.code}</strong> is ready to start.`); }
  else if (action === 'start') { job.status = 'In Progress'; job.assignments.forEach(a => { if (a.status === 'Assigned') a.status = 'Started'; }); addAudit(`Work started on ${job.code}`, 'Controlled job status transition'); toast('<strong>Work started.</strong> The bay is now active.'); }
  else if (action === 'complete-task') { job.status = 'Ready for Quality Check'; job.assignments.forEach(a => { if (a.status === 'Started') a.status = 'Completed'; }); addAudit(`Tasks completed on ${job.code}`, 'Commission remains pending quality'); toast('<strong>Ready for quality.</strong> Commission is still pending approval.'); }
  else if (action === 'approve-quality') { if (!can('quality')) return toast('<strong>Permission required.</strong> A worker cannot approve quality.', true); job.status = 'Ready for Payment'; job.quality = { ...(job.quality || {}), outcome: 'Passed' }; job.assignments.forEach(a => { if (a.status === 'Completed') a.status = 'Quality Approved'; }); addAudit(`Quality approved for ${job.code}`, 'Approved by current authorized reviewer'); toast('<strong>Quality approved.</strong> Payment can now be collected.'); }
  else if (action === 'rework') { job.status = 'Rework Required'; job.quality = { ...(job.quality || {}), outcome: 'Minor Rework' }; addAudit(`Rework requested for ${job.code}`, 'Quality outcome recorded'); toast('<strong>Rework recorded.</strong> No extra commission was created.', true); }
  else if (action === 'payment') paymentModal(job);
  else if (action === 'history') { openModal('Immutable job history', `${job.code} · Original records are preserved`, `<div class="audit-list" style="padding:0">${state.audit.filter(a => a.text.includes(job.code) || a.text.includes('quality')).map(a => `<div class="audit-row"><span class="audit-dot"></span><div><b>${a.text}</b><small>${a.detail}</small></div><span class="audit-time">${a.time}</span></div>`).join('') || '<div class="empty-state">No additional events on this job.</div>'}</div>`, '<button class="primary-button" data-close-modal>Close</button>'); }
  persist(); render();
}

function submitNewJob(form) { const data = new FormData(form); const service = data.get('service'); const type = data.get('vehicleType'); const original = serviceCatalog[service].prices[type] || 0; const discount = Math.max(0, Number(data.get('discount') || 0)); const selected = data.getAll('workers'); const rules = serviceCatalog[service].rules; const assignments = selected.map((id, i) => assignment(id, rules[i]?.[0] || 'Assigned worker', rules[i]?.[1] || 5, 'Assigned')); const id = `j${Date.now()}`; const job = { id, code: `CW-2026-${String(state.jobs.length + 125).padStart(6, '0')}`, plate: data.get('plate'), vehicleType: type, brand: data.get('brand') || 'Unknown', model: data.get('model') || '—', color: '—', customer: data.get('customer') || 'Walk-in customer', phone: data.get('phone') || '', arrival: '13:42', service, originalPrice: original, discount, finalPrice: original - discount, status: assignments.length ? 'Assigned' : 'Waiting', paymentStatus: 'Unpaid', bay: data.get('bay'), assignments, quality: { outcome: 'Pending', checklist: [] } }; state.jobs.unshift(job); state.selectedJobId = id; addAudit(`Created ${job.code}`, `${service} snapshot · ${money(job.finalPrice)} toman`); persist(); closeModal(); currentView = 'operations'; render(); toast(`<strong>${job.code}</strong> created with a preserved price snapshot.`); }
function submitPayment(form) { const job = getJob(); const data = new FormData(form); const amount = Number(data.get('amount') || 0); const tip = Number(data.get('tip') || 0); if (amount < job.finalPrice) return toast('<strong>Payment is incomplete.</strong> Record the full amount due or use approved customer credit.', true); if (amount > job.finalPrice + tip) return toast('<strong>Overpayment blocked.</strong> The difference must be recorded as a tip.', true); job.payments = [{ method: data.get('method'), amount: job.finalPrice }]; job.paymentStatus = 'Paid'; job.status = 'Completed'; job.assignments.forEach(a => { if (a.status === 'Quality Approved' || a.status === 'Completed') a.status = 'Earned'; }); if (data.get('method') === 'Cash') state.cash.payments += job.finalPrice; addAudit(`Payment recorded for ${job.code}`, `${data.get('method')} · ${money(job.finalPrice)} toman · tip ${money(tip)}`); persist(); closeModal(); render(); toast(`<strong>Payment recorded.</strong> ${job.code} is completed and commissions are earned.`); }
function submitExpense(form) { const data = new FormData(form); const amount = Number(data.get('amount') || 0); const expense = { id: `e${Date.now()}`, name: data.get('name'), category: data.get('category'), source: data.get('source'), createdBy: state.role === 'Owner' ? 'Morteza K.' : state.role, amount, status: data.get('status') }; state.expenses.unshift(expense); if (expense.source === 'Cash') state.cash.expenses += amount; addAudit(`Created expense: ${expense.name}`, `${money(amount)} toman · ${expense.category}`); persist(); closeModal(); render(); toast(`<strong>Expense saved.</strong> Ledger entry is ready for review.`); }

document.addEventListener('click', event => {
  const nav = event.target.closest('[data-view]'); if (nav) { currentView = nav.dataset.view; render(); return; }
  const link = event.target.closest('[data-view-link]'); if (link) { currentView = link.dataset.viewLink; render(); return; }
  const jobRow = event.target.closest('[data-job-id]'); if (jobRow) { state.selectedJobId = jobRow.dataset.jobId; render(); return; }
  const filter = event.target.closest('[data-filter]'); if (filter) { state.jobFilter = filter.dataset.filter; document.querySelectorAll('[data-filter]').forEach(el => el.classList.toggle('active', el.dataset.filter === state.jobFilter)); render(); return; }
  const action = event.target.closest('[data-action]'); if (action) { handleAction(action.dataset.action); return; }
  if (event.target.closest('[data-close-modal]') || event.target.id === 'modal-backdrop') closeModal();
  if (event.target.closest('#new-job-btn') || event.target.closest('#new-job-btn-2')) newJobModal();
  if (event.target.closest('#notifications-btn')) notificationModal();
  if (event.target.closest('#shift-summary-btn')) shiftModal();
  if (event.target.closest('#expense-btn')) { if (can('expense')) expenseModal(); else toast('<strong>Permission required.</strong> This role cannot add expenses.', true); }
  if (event.target.closest('#roles-btn')) rolesModal();
  if (event.target.closest('#cash-reconcile-btn') || event.target.closest('#cash-detail-btn')) shiftModal();
  if (event.target.closest('#refresh-btn')) { toast('<strong>Branch data refreshed.</strong> All totals are current.'); render(); }
  if (event.target.closest('#payroll-btn')) { if (can('payroll')) openModal('Weekly payroll review', 'Saturday 25 July — Friday 31 July · approval workflow', `<div class="commission-box"><b>3 workers ready for manager review</b><p>Total estimated payable: 4,860,000 toman. Owner approval is required before payment. No user can approve their own statement.</p></div><div class="detail-line"><span>Opening unpaid balance</span><b>1,200,000 toman</b></div><div class="detail-line"><span>Earned commissions</span><b>3,400,000 toman</b></div><div class="detail-line"><span>Tips and bonuses</span><b>260,000 toman</b></div>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" data-close-modal>Mark manager reviewed</button>'); else toast('<strong>Permission required.</strong> Payroll approval is restricted.', true); }
  if (event.target.closest('#export-earnings-btn') || event.target.closest('#export-report-btn')) { downloadCSV(); toast('<strong>CSV export prepared.</strong>'); }
  const report = event.target.closest('[data-report]'); if (report) { downloadCSV(report.dataset.report); toast(`<strong>${report.dataset.report}</strong> export prepared.`); }
});
document.addEventListener('submit', event => { if (event.target.id === 'new-job-form') { event.preventDefault(); submitNewJob(event.target); } if (event.target.id === 'payment-form') { event.preventDefault(); submitPayment(event.target); } if (event.target.id === 'expense-form') { event.preventDefault(); submitExpense(event.target); } });
document.getElementById('role-select').addEventListener('change', event => { state.role = event.target.value.replace(' view', '').replace('Branch Manager', 'Branch Manager'); if (state.role === 'Owner') state.role = 'Owner'; persist(); render(); toast(`<strong>${event.target.value}</strong> enabled. Permissions and data scope updated.`); });
document.getElementById('job-search').addEventListener('input', renderOperations);

function downloadCSV(reportName = 'ShinePro report') { const rows = [['Job code', 'Plate', 'Service', 'Status', 'Payment status', 'Final price', 'Commission']].concat(state.jobs.map(j => [j.code, j.plate, j.service, j.status, j.paymentStatus, j.finalPrice, totalCommission(j)])); const csv = rows.map(row => row.map(v => `"${String(v).replaceAll('"', '""')}"`).join(',')).join('\n'); const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `${reportName.toLowerCase().replaceAll(' ', '-')}.csv`; link.click(); URL.revokeObjectURL(link.href); }

render();

function renderCustomers() {
  const list = document.getElementById('customer-list'); if (!list) return;
  const search = (document.getElementById('customer-search')?.value || '').toLowerCase();
  const customers = state.customers.filter(c => [c.name, c.phone, ...c.vehicles].join(' ').toLowerCase().includes(search)).filter(c => state.customerFilter === 'all' || (state.customerFilter === 'loyal' && c.type === 'Loyalty') || (state.customerFilter === 'credit' && c.credit > 0));
  list.innerHTML = customers.map(c => `<div class="customer-row ${c.id === state.selectedCustomerId ? 'selected' : ''}" data-customer-id="${c.id}"><div class="avatar avatar-${c.color}">${c.name.split(' ').map(x => x[0]).join('').slice(0,2)}</div><div><b>${c.name}</b><small>${c.phone} · ${c.vehicles.length} vehicle${c.vehicles.length > 1 ? 's' : ''}</small></div><div class="customer-row-end"><span class="status-pill ${c.credit ? 'amber' : 'green'}">${c.credit ? 'Credit' : c.type}</span><small>${money(c.spend, true)} spent</small></div></div>`).join('') || '<div class="empty-state"><b>No customers found</b><span>Try another search or add a customer.</span><br><button class="primary-button" data-action="add-customer">+ Add customer</button></div>';
  const detail = document.getElementById('customer-detail'); const c = state.customers.find(x => x.id === state.selectedCustomerId); if (!detail || !c) return;
  detail.innerHTML = `<div class="detail-top"><div class="detail-code"><div><h3>${c.name}</h3><small>${c.type} customer · ${c.phone}</small></div><button class="icon-button" data-customer-action="menu" aria-label="Customer actions" title="Customer actions">•••</button></div><div class="detail-meta"><span class="status-pill green">${c.status}</span>${c.credit ? '<span class="status-pill amber">Credit account</span>' : ''}</div></div><div class="detail-section"><h4>Customer profile</h4><div class="detail-line"><span>Total visits</span><b>${c.visits}</b></div><div class="detail-line"><span>Total spending</span><b>${money(c.spend)} toman</b></div><div class="detail-line"><span>Outstanding credit</span><b class="${c.credit ? 'amount' : ''}">${money(c.credit)} toman</b></div><div class="detail-line"><span>Notes</span><b>${c.note || 'No note added'}</b></div></div><div class="detail-section"><h4>Vehicles <button class="text-button" style="float:right" data-customer-action="add-vehicle">+ Add vehicle</button></h4>${c.vehicles.map(v => `<div class="portal-vehicle"><span class="vehicle-icon">▱</span><div><b>${v}</b><small>Service history available</small></div><button class="round-arrow" data-customer-action="edit-vehicle" aria-label="Edit vehicle">→</button></div>`).join('')}</div><div class="detail-section"><h4>Recent activity</h4><div class="detail-line"><span>Latest job</span><b>CW-2026-000124 · Full Wash</b></div><div class="detail-line"><span>Membership</span><b>Shine Plus · 2 visits left</b></div></div><div class="detail-actions"><button class="primary-button" data-customer-action="edit">Edit customer</button><button class="ghost-button" data-customer-action="history">View history</button></div>`;
}

function renderInventory() {
  const table = document.getElementById('inventory-table'); if (!table) return;
  const items = state.inventory.filter(i => state.stockFilter === 'all' || (state.stockFilter === 'low' && i.stock < i.minimum) || (state.stockFilter === 'inactive' && i.status === 'Inactive'));
  table.innerHTML = items.map(i => `<tr><td><div class="worker-cell"><div class="report-card-icon ${i.stock < i.minimum ? 'amber' : 'green'}">▦</div><div><b>${i.name}</b><small>${i.category} · ${i.status}</small></div></div></td><td class="amount ${i.stock < i.minimum ? 'low-stock' : ''}">${i.stock}</td><td class="amount">${i.minimum}</td><td>${i.unit}</td><td class="amount">${money(i.cost)} toman</td><td><small>${i.movement}</small></td><td><button class="row-action" data-stock-action="edit" data-item-id="${i.id}" aria-label="Edit ${i.name}">Edit</button><button class="row-action" data-stock-action="movement" data-item-id="${i.id}" aria-label="Record movement for ${i.name}">Move</button></td></tr>`).join('') || '<tr><td colspan="7"><div class="empty-state"><b>No inventory items in this filter</b><button class="primary-button" data-action="add-item">+ Add item</button></div></td></tr>';
  const metrics = [['Items tracked', state.inventory.filter(i => i.status === 'Active').length, '', 'Active catalogue', 'green'], ['Low stock', state.inventory.filter(i => i.status === 'Active' && i.stock < i.minimum).length, '', 'Purchase recommended', 'warn'], ['Estimated stock value', state.inventory.reduce((s, i) => s + i.stock * i.cost, 0), 'toman', 'Based on average cost', 'green'], ['Movements this week', 28, '', 'Purchase, usage and waste', 'green']];
  const target = document.getElementById('inventory-metrics'); if (target) target.innerHTML = metrics.map(m => metricTemplate(...m)).join('');
}

function renderInbox() {
  const list = document.getElementById('inbox-list'); if (!list) return;
  const items = state.inbox.filter(n => state.inboxFilter === 'all' || n.type === state.inboxFilter);
  list.innerHTML = items.map(n => `<div class="inbox-row ${n.read ? 'read' : ''}"><span class="review-icon ${n.type === 'approval' ? 'amber' : n.type === 'warning' ? 'red' : 'blue'}">${n.icon}</span><div class="inbox-copy"><b>${n.title}</b><small>${n.detail}</small><span>${n.age}</span></div><div class="inbox-actions"><button class="ghost-button" data-inbox-action="open" data-inbox-id="${n.id}">${n.action}</button><button class="icon-button small" data-inbox-action="history" data-inbox-id="${n.id}" aria-label="View notification history" title="View history">•••</button></div></div>`).join('') || '<div class="empty-state"><b>All clear</b><span>No items need attention in this filter.</span></div>';
}

function renderSettings() {
  const grid = document.getElementById('config-grid'); if (!grid) return;
  grid.innerHTML = state.settings.map(s => `<article class="config-card"><div class="config-card-icon">${s.icon}</div><div class="config-card-copy"><h3>${s.title}</h3><p>${s.detail}</p><small>Managed by ${s.owner}</small></div><button class="ghost-button" data-config-action="open" data-config-id="${s.id}">${s.action} →</button></article>`).join('');
}

function customerModal(existing = null) {
  const c = existing || { name: '', phone: '', type: 'Walk-in', note: '' };
  openModal(existing ? 'Edit customer profile' : 'Add customer', 'Customer fields are editable until financial history is posted.', `<form id="customer-form"><div class="form-grid"><div class="form-field full"><label>Name *</label><input name="name" value="${c.name}" required /></div><div class="form-field"><label>Phone number *</label><input name="phone" value="${c.phone}" required /></div><div class="form-field"><label>Customer type</label><select name="type"><option ${c.type === 'Walk-in' ? 'selected' : ''}>Walk-in</option><option ${c.type === 'Loyalty' ? 'selected' : ''}>Loyalty</option><option ${c.type === 'Business' ? 'selected' : ''}>Business</option><option ${c.type === 'Fleet' ? 'selected' : ''}>Fleet</option></select></div><div class="form-field full"><label>Note</label><textarea name="note">${c.note || ''}</textarea></div></div></form>`, `<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="customer-form">${existing ? 'Save profile' : 'Create customer'}</button>`);
  document.getElementById('customer-form').dataset.customerId = existing?.id || '';
}
function vehicleModal(customer = null) { openModal('Add vehicle', 'Vehicle details are editable; completed service history remains locked.', `<form id="vehicle-form"><div class="form-grid"><div class="form-field"><label>Registration plate *</label><input name="plate" required placeholder="21 ب 482 ایران 11" /></div><div class="form-field"><label>Vehicle type</label><select name="vehicleType"><option>Small</option><option selected>Sedan</option><option>SUV</option><option>Van</option></select></div><div class="form-field"><label>Brand</label><input name="brand" placeholder="Kia" /></div><div class="form-field"><label>Model</label><input name="model" placeholder="Cerato" /></div><div class="form-field"><label>Colour</label><input name="color" placeholder="White" /></div><div class="form-field"><label>Customer</label><select name="customer">${state.customers.map(c => `<option value="${c.id}" ${customer?.id === c.id ? 'selected' : ''}>${c.name}</option>`).join('')}</select></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="vehicle-form">Save vehicle</button>'); }
function inventoryModal(item = null, movement = false) { if (movement) { openModal('Record stock movement', `${item.name} · balance is system calculated`, `<form id="stock-movement-form"><div class="form-grid"><div class="form-field"><label>Movement type</label><select name="type"><option>Purchase</option><option>Usage</option><option>Waste</option><option>Return</option><option>Adjustment</option></select></div><div class="form-field"><label>Quantity</label><input name="quantity" type="number" min="0" required /></div><div class="form-field full"><label>Reason *</label><textarea name="reason" required placeholder="Explain the movement or adjustment"></textarea></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="stock-movement-form">Post movement</button>'); document.getElementById('stock-movement-form').dataset.itemId = item.id; return; } const i = item || { name: '', category: 'Chemicals', stock: 0, minimum: 0, unit: 'L', cost: 0 }; openModal(item ? 'Edit inventory item' : 'Add inventory item', 'Stock balance cannot be typed directly; use a movement or adjustment record.', `<form id="inventory-form"><div class="form-grid"><div class="form-field full"><label>Item name *</label><input name="name" value="${i.name}" required /></div><div class="form-field"><label>Category</label><input name="category" value="${i.category}" /></div><div class="form-field"><label>Unit</label><input name="unit" value="${i.unit}" /></div><div class="form-field"><label>Minimum stock</label><input name="minimum" type="number" min="0" value="${i.minimum}" /></div><div class="form-field"><label>Average cost (toman)</label><input name="cost" type="number" min="0" value="${i.cost}" /></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="inventory-form">Save item</button>'); document.getElementById('inventory-form').dataset.itemId = item?.id || ''; }
function configModal(id) { const s = state.settings.find(x => x.id === id); if (!s) return; const locked = !can('settings'); openModal(s.title, `${s.detail} · ${locked ? 'Read-only for this role' : 'Changes are versioned with an effective date.'}`, `<div class="config-edit-panel"><div class="detail-line"><span>Owner</span><b>${s.owner}</b></div><div class="detail-line"><span>Current version</span><b>v3 · Effective 28 Jul 2026</b></div><div class="detail-line"><span>Historical records</span><b>Preserved</b></div><div class="form-field"><label>Configuration note</label><textarea ${locked ? 'disabled' : ''} placeholder="Describe the intended change"></textarea></div><div class="commission-box"><b>Editing rule</b><p>${locked ? 'You can view this criterion, but only an authorized administrator can change it.' : 'Changes create a new version. Completed jobs continue using their historical snapshot.'}</p></div></div>`, `<button class="ghost-button" data-close-modal>Close</button>${locked ? '' : '<button class="primary-button" data-config-save="' + id + '">Save new version</button>'}`); }
function jobMenuModal(job) { const locked = job.status === 'Completed'; openModal('Job actions', `${job.code} · ${locked ? 'Locked after completion' : 'Editable until quality approval'}`, `<div class="action-menu-grid"><button class="action-menu-item" data-action="edit-job">Edit job <small>${locked ? 'Correction workflow' : 'Draft fields available'}</small></button><button class="action-menu-item" data-action="duplicate-job">Duplicate job <small>Create a new draft</small></button><button class="action-menu-item" data-action="history">View audit history <small>Immutable activity</small></button><button class="action-menu-item" data-action="print-receipt">Print ticket <small>Readable job code</small></button><button class="action-menu-item" data-action="refund">Request refund <small>Approval required</small></button><button class="action-menu-item" data-action="archive-job">Archive draft <small>Only drafts can be archived</small></button></div>`, '<button class="primary-button" data-close-modal>Close</button>'); }
function correctionModal(job, refund = false) { const title = refund ? 'Request refund' : 'Create correction'; openModal(title, `${job.code} · original record remains visible`, `<form id="correction-form"><div class="commission-box"><b>${refund ? 'Refund creates a reversal and worker adjustment when needed.' : 'Completed records are not overwritten.'}</b><p>Original price: ${money(job.originalPrice)} · Final price: ${money(job.finalPrice)} · Payment status: ${job.paymentStatus}</p></div><div class="form-grid"><div class="form-field"><label>${refund ? 'Refund amount' : 'Correction amount'} (toman)</label><input name="amount" type="number" value="${refund ? job.finalPrice : 0}" min="0" max="${job.finalPrice}" required /></div><div class="form-field"><label>Reason *</label><input name="reason" required placeholder="Required for audit history" /></div><div class="form-field full"><label>Supporting note</label><textarea name="note" placeholder="What should the reviewer know?"></textarea></div></div></form>`, `<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="correction-form">Submit for approval</button>`); document.getElementById('correction-form').dataset.jobId = job.id; document.getElementById('correction-form').dataset.refund = refund ? 'true' : 'false'; }
function bookingModal() { openModal('Book a service', 'Customer-facing booking preview · final price is confirmed by the cashier.', `<form id="booking-form"><div class="form-grid"><div class="form-field"><label>Vehicle</label><select><option>Kia Cerato · 21 ب 482 ایران 11</option><option>Toyota RAV4 · 12 ل 780 ایران 68</option></select></div><div class="form-field"><label>Branch</label><select><option>Tehran · Vanak</option></select></div><div class="form-field"><label>Service</label><select>${Object.keys(serviceCatalog).map(s => `<option>${s}</option>`).join('')}</select></div><div class="form-field"><label>Preferred time</label><select><option>Today · 15:00</option><option>Tomorrow · 09:00</option></select></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" data-close-modal>Request booking</button>'); }

function jobEditModal(job) { openModal('Edit draft job', `${job.code} · editable before quality approval`, `<form id="job-edit-form"><div class="form-grid"><div class="form-field"><label>Registration plate</label><input name="plate" value="${job.plate}" required /></div><div class="form-field"><label>Bay</label><select name="bay">${['Unassigned','Bay 01','Bay 02','Bay 03','Bay 04','Bay 05'].map(b => `<option ${job.bay === b ? 'selected' : ''}>${b}</option>`).join('')}</select></div><div class="form-field full"><label>Job note</label><textarea name="notes">${job.notes || ''}</textarea></div><div class="form-field full"><label>Editability</label><div class="commission-box"><b>Draft fields are editable until quality approval.</b><p>Service price and commission are historical snapshots; change them through a correction or new version.</p></div></div></div></form>`, '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="job-edit-form">Save and continue</button>'); document.getElementById('job-edit-form').dataset.jobId = job.id; }

document.addEventListener('click', event => {
  const customerRow = event.target.closest('[data-customer-id]'); if (customerRow) { state.selectedCustomerId = customerRow.dataset.customerId; renderCustomers(); return; }
  const customerFilter = event.target.closest('[data-customer-filter]'); if (customerFilter) { state.customerFilter = customerFilter.dataset.customerFilter; document.querySelectorAll('[data-customer-filter]').forEach(x => x.classList.toggle('active', x.dataset.customerFilter === state.customerFilter)); renderCustomers(); return; }
  const stockFilter = event.target.closest('[data-stock-filter]'); if (stockFilter) { state.stockFilter = stockFilter.dataset.stockFilter; document.querySelectorAll('[data-stock-filter]').forEach(x => x.classList.toggle('active', x.dataset.stockFilter === state.stockFilter)); renderInventory(); return; }
  const stockAction = event.target.closest('[data-stock-action]'); if (stockAction) { const item = state.inventory.find(i => i.id === stockAction.dataset.itemId); if (stockAction.dataset.stockAction === 'edit') inventoryModal(item); else inventoryModal(item, true); return; }
  const inboxFilter = event.target.closest('[data-inbox-filter]'); if (inboxFilter) { state.inboxFilter = inboxFilter.dataset.inboxFilter; document.querySelectorAll('[data-inbox-filter]').forEach(x => x.classList.toggle('active', x.dataset.inboxFilter === state.inboxFilter)); renderInbox(); return; }
  const inboxAction = event.target.closest('[data-inbox-action]'); if (inboxAction) { const item = state.inbox.find(n => n.id === inboxAction.dataset.inboxId); if (inboxAction.dataset.inboxAction === 'history') { openModal('Inbox history', item.title, `<div class="audit-list" style="padding:0"><div class="audit-row"><span class="audit-dot"></span><div><b>Created by workflow engine</b><small>${item.detail}</small></div><span class="audit-time">${item.age}</span></div></div>`, '<button class="primary-button" data-close-modal>Close</button>'); } else { item.read = true; if (item.jobId) { state.selectedJobId = item.jobId; currentView = item.title.includes('quality') ? 'operations' : 'inbox'; } persist(); render(); toast(`<strong>${item.action}</strong> opened.`); } return; }
  const configAction = event.target.closest('[data-config-action]'); if (configAction) { configModal(configAction.dataset.configId); return; }
  const configSave = event.target.closest('[data-config-save]'); if (configSave) { if (!can('settings')) return toast('<strong>Permission required.</strong> Configuration is read-only for this role.', true); addAudit(`Created new configuration version: ${configSave.dataset.configSave}`, 'Effective date recorded; historical records preserved'); persist(); closeModal(); toast('<strong>New version saved.</strong> Previous criteria remain available in history.'); return; }
  if (event.target.closest('#add-customer-btn') || event.target.closest('[data-action="add-customer"]')) { if (can('customer')) customerModal(); else toast('<strong>Permission required.</strong> This role cannot create customers.', true); return; }
  if (event.target.closest('#add-vehicle-btn') || event.target.closest('#portal-add-vehicle') || event.target.closest('[data-customer-action="add-vehicle"]')) { vehicleModal(state.customers.find(c => c.id === state.selectedCustomerId)); return; }
  if (event.target.closest('#portal-btn')) { currentView = 'portal'; render(); return; }
  if (event.target.closest('#book-service-btn')) { bookingModal(); return; }
  if (event.target.closest('#portal-notifications-btn')) { currentView = 'inbox'; render(); return; }
  if (event.target.closest('#add-item-btn') || event.target.closest('[data-action="add-item"]')) { if (can('inventory')) inventoryModal(); else toast('<strong>Permission required.</strong> Inventory changes are restricted.', true); return; }
  if (event.target.closest('#stock-movement-btn')) { const item = state.inventory.find(i => i.status === 'Active'); inventoryModal(item, true); return; }
  if (event.target.closest('#supplier-btn')) { openModal('Suppliers', 'Inventory supplier records are managed separately from stock balance.', '<div class="empty-state"><b>2 suppliers configured</b><span>Add supplier records and attach invoices from this page.</span></div>', '<button class="primary-button" data-close-modal>Add supplier</button>'); return; }
  if (event.target.closest('#add-worker-btn')) { openModal('Add worker', 'Worker profiles, branch assignments and role permissions are auditable.', '<form id="worker-form"><div class="form-grid"><div class="form-field"><label>Full name *</label><input name="name" required /></div><div class="form-field"><label>Phone</label><input name="phone" /></div><div class="form-field"><label>Role</label><select name="role"><option>Car-wash worker</option><option>Team Leader</option><option>Quality Controller</option><option>Cashier</option></select></div><div class="form-field"><label>Branch</label><select><option>Tehran · Vanak</option></select></div></div></form>', '<button class="ghost-button" data-close-modal>Cancel</button><button class="primary-button" type="submit" form="worker-form">Create worker</button>'); return; }
  if (event.target.closest('#print-queue-btn')) { toast('<strong>Print view prepared.</strong> Use your browser print dialog.'); window.print(); }
  if (event.target.closest('#permission-matrix-btn')) rolesModal();
  if (event.target.closest('#save-settings-btn')) { if (can('settings')) { addAudit('Saved configuration center changes', 'New versions preserve historical snapshots'); persist(); toast('<strong>Configuration saved.</strong> Historical snapshots remain locked.'); } else toast('<strong>Permission required.</strong> Only an authorized administrator can save settings.', true); }
  if (event.target.closest('#mark-inbox-btn')) { state.inbox.forEach(n => n.read = true); persist(); renderInbox(); toast('<strong>Inbox marked as read.</strong>'); }
  if (event.target.closest('#inbox-filter-btn')) { currentView = 'inbox'; render(); }
  if (event.target.closest('#language-btn')) { state.language = state.language === 'en' ? 'fa' : 'en'; document.documentElement.dir = state.language === 'fa' ? 'rtl' : 'ltr'; document.documentElement.lang = state.language === 'fa' ? 'fa' : 'en'; persist(); toast(`<strong>${state.language === 'fa' ? 'فارسی' : 'English'}</strong> direction is ready.`); }
  if (event.target.closest('#portal-edit-vehicle') || event.target.closest('[data-customer-action="edit-vehicle"]')) vehicleModal(state.customers.find(c => c.id === state.selectedCustomerId));
  if (event.target.closest('[data-customer-action="edit"]')) customerModal(state.customers.find(c => c.id === state.selectedCustomerId));
  if (event.target.closest('[data-customer-action="history"]')) openModal('Customer history', 'Visits, receipts and memberships remain linked to source records.', '<div class="audit-list" style="padding:0"><div class="audit-row"><span class="audit-dot"></span><div><b>12 completed visits</b><small>Latest: CW-2026-000124 · Full Wash</small></div><span class="audit-time">Today</span></div></div>', '<button class="primary-button" data-close-modal>Close</button>');
  if (event.target.closest('[data-action="job-menu"]')) jobMenuModal(getJob());
  if (event.target.closest('[data-action="correction"]')) correctionModal(getJob());
  if (event.target.closest('[data-action="refund"]')) correctionModal(getJob(), true);
  if (event.target.closest('[data-action="edit-job"]')) { closeModal(); if (getJob().status === 'Completed') correctionModal(getJob()); else jobEditModal(getJob()); }
  if (event.target.closest('[data-action="duplicate-job"]')) { const j = getJob(); const copy = { ...j, id: `j${Date.now()}`, code: `CW-2026-${String(state.jobs.length + 125).padStart(6, '0')}`, status: 'Waiting', paymentStatus: 'Unpaid', assignments: [], payments: undefined }; state.jobs.unshift(copy); state.selectedJobId = copy.id; persist(); closeModal(); currentView = 'operations'; render(); toast(`<strong>${copy.code}</strong> duplicated as a draft.`); }
  if (event.target.closest('[data-action="archive-job"]')) { const j = getJob(); if (j.status !== 'Waiting') toast('<strong>Archive unavailable.</strong> Only draft jobs can be archived.', true); else { j.archived = true; addAudit(`Archived draft ${j.code}`, 'Draft record retained for audit'); persist(); render(); toast('<strong>Draft archived.</strong>'); } }
  if (event.target.closest('[data-action="print-receipt"]')) { toast('<strong>Print view prepared.</strong> Use your browser print dialog.'); window.print(); }
});

document.addEventListener('submit', event => {
  if (event.target.id === 'job-edit-form') { event.preventDefault(); const job = state.jobs.find(j => j.id === event.target.dataset.jobId); const data = new FormData(event.target); if (job) { job.plate = data.get('plate'); job.bay = data.get('bay'); job.notes = data.get('notes'); addAudit(`Edited draft ${job.code}`, 'Draft fields updated before quality approval'); persist(); closeModal(); render(); toast('<strong>Draft job updated.</strong>'); } }
  if (event.target.id === 'worker-form') { event.preventDefault(); const data = new FormData(event.target); const name = data.get('name'); const initials = name.split(' ').map(x => x[0]).join('').slice(0,2).toUpperCase(); state.workers.push({ id: `w${Date.now()}`, name, initials, role: data.get('role'), title: data.get('role'), color: 'green', present: false, quality: 0, completed: 0, payable: 0 }); addAudit(`Created worker profile: ${name}`, 'Branch assignment and role recorded'); persist(); closeModal(); currentView = 'team'; render(); toast(`<strong>${name}</strong> added to the team.`); }
  if (event.target.id === 'customer-form') { event.preventDefault(); const data = new FormData(event.target); const id = event.target.dataset.customerId; const c = state.customers.find(x => x.id === id); if (c) Object.assign(c, { name: data.get('name'), phone: data.get('phone'), type: data.get('type'), note: data.get('note') }); else state.customers.unshift({ id: `c${Date.now()}`, name: data.get('name'), phone: data.get('phone'), type: data.get('type'), status: 'Active', visits: 0, spend: 0, credit: 0, vehicles: [], note: data.get('note'), color: 'green' }); addAudit(`${c ? 'Edited' : 'Created'} customer profile`, 'Customer record action'); persist(); closeModal(); currentView = 'customers'; render(); toast(`<strong>Customer ${c ? 'updated' : 'created'}.</strong>`); }
  if (event.target.id === 'vehicle-form') { event.preventDefault(); const data = new FormData(event.target); const c = state.customers.find(x => x.id === data.get('customer')); if (c) c.vehicles.push(`${data.get('brand') || 'Vehicle'} ${data.get('model') || ''} · ${data.get('plate')}`.trim()); addAudit('Added vehicle profile', 'Vehicle record linked to customer'); persist(); closeModal(); currentView = 'customers'; render(); toast('<strong>Vehicle saved.</strong>'); }
  if (event.target.id === 'inventory-form') { event.preventDefault(); const data = new FormData(event.target); const id = event.target.dataset.itemId; const i = state.inventory.find(x => x.id === id); if (i) Object.assign(i, { name: data.get('name'), category: data.get('category'), unit: data.get('unit'), minimum: Number(data.get('minimum') || 0), cost: Number(data.get('cost') || 0) }); else state.inventory.push({ id: `i${Date.now()}`, name: data.get('name'), category: data.get('category'), unit: data.get('unit'), stock: 0, minimum: Number(data.get('minimum') || 0), cost: Number(data.get('cost') || 0), movement: 'Created · today', status: 'Active' }); addAudit(`${i ? 'Edited' : 'Added'} inventory item`, 'Stock balance remains system calculated'); persist(); closeModal(); currentView = 'inventory'; render(); toast(`<strong>Inventory item ${i ? 'updated' : 'created'}.</strong>`); }
  if (event.target.id === 'stock-movement-form') { event.preventDefault(); const data = new FormData(event.target); const i = state.inventory.find(x => x.id === event.target.dataset.itemId); const qty = Number(data.get('quantity') || 0); if (i) { const sign = ['Purchase', 'Return'].includes(data.get('type')) ? 1 : -1; i.stock = Math.max(0, i.stock + sign * qty); i.movement = `${data.get('type')} · just now`; } addAudit(`Posted stock movement for ${i?.name || 'item'}`, `${data.get('type')} · ${qty} ${i?.unit || ''} · reason recorded`); persist(); closeModal(); render(); toast('<strong>Stock movement posted.</strong> Balance recalculated.'); }
  if (event.target.id === 'correction-form') { event.preventDefault(); const job = state.jobs.find(j => j.id === event.target.dataset.jobId); const data = new FormData(event.target); addAudit(`${event.target.dataset.refund === 'true' ? 'Refund request' : 'Correction request'} for ${job.code}`, `${money(data.get('amount'))} toman · ${data.get('reason')}`); persist(); closeModal(); render(); toast('<strong>Request submitted.</strong> Original record remains unchanged.'); }
  if (event.target.id === 'payment-form' || event.target.id === 'expense-form' || event.target.id === 'new-job-form') { return; }
});

const customerSearch = document.getElementById('customer-search'); if (customerSearch) customerSearch.addEventListener('input', renderCustomers);
if (state.language === 'fa') { document.documentElement.dir = 'rtl'; document.documentElement.lang = 'fa'; }

function ensureLanguageButton() {
  const actions = document.querySelector('.topbar-actions');
  if (actions && !document.getElementById('language-btn')) actions.insertAdjacentHTML('afterbegin', '<button class="ghost-button language-button" id="language-btn" aria-label="Switch interface language" title="Switch interface language">EN / فارسی</button>');
}

document.getElementById('role-select').addEventListener('change', () => {
  if (state.role === 'Customer') currentView = 'portal';
  else if (currentView === 'portal') currentView = 'overview';
  render();
});

function decorateDetailActions() {
  const detail = document.getElementById('job-detail'); const job = getJob(); if (!detail || !job) return;
  const top = detail.querySelector('.detail-top'); if (top && !top.querySelector('[data-action="job-menu"]')) top.insertAdjacentHTML('beforeend', '<button class="icon-button" data-action="job-menu" aria-label="Open job actions" title="Job actions">•••</button>');
  const actions = detail.querySelector('.detail-actions'); if (!actions) return;
  if (job.status === 'Ready for Quality Check') actions.insertAdjacentHTML('afterbegin', '<button class="disabled-button" disabled title="Quality approval is required before completion">Complete job <small>Quality approval required</small></button>');
  if (job.status === 'Completed') actions.insertAdjacentHTML('beforeend', '<button class="ghost-button" data-action="correction">Create correction</button><button class="ghost-button" data-action="refund">Request refund</button>');
  if (window.innerWidth < 800 && !detail.querySelector('.mobile-action-bar')) detail.insertAdjacentHTML('beforeend', `<div class="mobile-action-bar">${actions.innerHTML}</div>`);
}
